Let \[f(x) = \left\{
\begin{array}{cl}
\frac{x}{3} - 1 & \text{if } x \le 0, \\
-2x + 5 & \text{if } x > 0.
\end{array}
\right.\]Find the sum of all values of $x$ such that \(f(x) = 2\).

Let
\[ g(x) = \left\{
\begin{array}{cl}
x + 2 & \text{if $x < 10$}, \\
3x + 1 & \text{if $x \ge 10$}.
\end{array}
\right.\]
Find $g^{-1}(5) + g^{-1}(28)$.

Below is the graph of $y = a \sec bx$ for some positive constants $a$ and $b.$ Find $a.$

[asy]
import TrigMacros;

size(500);

real g(real x)
{
	return 3*sec(x/4);
}

draw(graph(g,-2*pi + 0.01, -pi - 0.01),red);
draw(graph(g,-pi + 0.01,0.01),red);
draw(graph(g,0.01,pi - 0.01),red);
draw(graph(g,pi + 0.01,2*pi - 0.01),red);
limits((-2*pi,-5),(2*pi,5),Crop);
draw((-pi,-5)--(-pi,5),dashed);
draw((pi,-5)--(pi,5),dashed);
trig_axes(-2*pi,2*pi,-5,5,pi/2,1);
layer();
rm_trig_labels(-11, 11, 2);

label("$1$", (0,1), E);
label("$3$", (0,3), E);
label("$-1$", (0,-1), E);
label("$-3$", (0,-3), E);
[/asy]

Determine the ordered pair $(x, y)$ if

\begin{align*}
x + y &= (7 - x) + (7 - y),\\
x - y &= (x - 2) + (y - 2).
\end{align*}

